package ru.livingvillages;

import org.junit.jupiter.api.Test;
import ru.livingvillages.domain.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class CivicWorksTest {
    private Village.Block cell(int x,int y,int z,int phase,String block){return new Village.Block(x,y,z,phase,"minecraft:air","minecraft:"+block,null);}
    @Test void streetCoverageUsesExteriorLightsAndDoesNotCountInteriorLamps(){var v=new Village();var road=new Village.Building();road.kind="road";v.buildings.add(road);var p=new Village.Project();p.kind="road";p.building=road.id;p.state="COMPLETE";p.blocks.add(cell(0,64,0,5,"dirt_path"));p.blocks.add(cell(2,68,0,4,"torch"));p.blocks.add(cell(2,67,0,3,"cobblestone"));v.projects.add(p);assertEquals(1,Lighting.roads(v,true).size());assertEquals(1,Lighting.lights(v).size());assertTrue(Lighting.covered(p.blocks.getFirst(),Lighting.lights(v),8));assertFalse(Lighting.covered(cell(12,64,0,5,"dirt_path"),Lighting.lights(v),8));}
    @Test void pendingAndCancelledLightsDoNotProduceDuplicateCoverage(){var v=new Village();var b=new Village.Building();b.kind="street_light";v.buildings.add(b);var a=new Village.Project();a.kind=b.kind;a.building=b.id;a.blocks.add(cell(4,68,2,4,"torch"));v.projects.add(a);assertTrue(Lighting.pending(v));a.state="COMPLETE";var repair=new Village.Project();repair.kind="Ремонт светильника";repair.building=b.id;repair.blocks.addAll(a.blocks);v.projects.add(repair);assertEquals(1,Lighting.lights(v).size());a.state="CANCELLED";repair.state="CANCELLED";assertTrue(Lighting.lights(v).isEmpty());}
    @Test void automaticRepairRanksFoodAndHousingAndNeverSelectsPrivateProperty(){var v=new Village();var rules=new Rules();rules.foods.put("CARROT",2);rules.recipes.put("garden",new Rules.Recipe("FARMER",Map.of(),Map.of("CARROT",24),"irrigated",1,1));var light=broken(v,"street_light");var home=broken(v,"residence");home.beds=6;var farm=broken(v,"garden");farm.recipe="garden";var personal=broken(v,"small");personal.owner=UUID.randomUUID();assertEquals(List.of(farm,home,light),Repairs.needed(v,rules));}
    @Test void anAlreadyReservedRepairIsNotIssuedTwice(){var v=new Village();var b=broken(v,"warehouse");var p=new Village.Project();p.building=b.id;v.projects.add(p);assertTrue(Repairs.needed(v,new Rules()).isEmpty());p.state="CANCELLED";assertEquals(List.of(b),Repairs.needed(v,new Rules()));}
    @Test void workStrollChangesOnlyTheVisibleCropPoint() throws Exception {var v=AutonomyData.village();var r=v.residents.get(2);var b=v.buildings.get(1);var p=v.projects.stream().filter(q->q.building.equals(b.id)).findFirst().orElseThrow();p.blocks.clear();p.blocks.add(cell(10,65,3,2,"carrots[age=7]"));p.blocks.add(cell(12,65,3,2,"carrots[age=7]"));var rules=AutonomyData.rules();var stock=new HashMap<>(v.stock.items);var first=Routines.plan(v,r,3000,0,0,rules,false);var second=Routines.plan(v,r,3000,0,1,rules,false);assertNotEquals(first.x(),second.x());assertEquals(stock,v.stock.items);assertEquals(0,v.days);assertEquals(b.id,r.workplace);}
    @Test void idleStrollDoesNotTurnIntoFreeWork() throws Exception {var v=AutonomyData.village();var r=v.residents.get(3);var rules=AutonomyData.rules();v.projects.clear();assertNotEquals(Routines.plan(v,r,3000,0,0,rules,false),Routines.plan(v,r,3000,0,1,rules,false));assertEquals(-1,r.economicDay);assertEquals(1024,v.treasury);}
    private Village.Building broken(Village v,String kind){var b=new Village.Building();b.kind=kind;b.complete=true;b.damaged=true;v.buildings.add(b);return b;}
    @Test void aWorkshopCanShelterPeopleEvenWithoutBeds(){var b=new Village.Building();b.kind="workshop";b.complete=true;assertEquals(0,b.beds);assertTrue(Shelters.usable(b));b.owner=UUID.randomUUID();assertFalse(Shelters.usable(b));b.owner=null;b.damaged=true;assertFalse(Shelters.usable(b));b.damaged=false;b.kind="street_light";assertFalse(Shelters.usable(b));}
}
